begin;

-- Keep the global catalog measurable: every active recipe ingredient gets a numeric norm.
update public.global_recipe_catalog_items i
set quantity = case
  when lower(g.name) ~ 'соль.*перец|перец.*соль' then 2.5
  when lower(g.name) ~ '^соль$|\\bсоль\\b' then 2.5
  when lower(g.name) ~ 'черн.*перец|бел.*перец|перец горошком|перец молот' then 0.5
  when lower(g.name) ~ 'чили|паприк|зир|кориандр|карри|куркум|имбир|мускат|корица|гвоздик|шафран|спец' then 1
  when lower(g.name) ~ 'масл|уксус|лимонн.*сок|сок лайм|соев.*соус|сироп' then 10
  when lower(g.name) ~ 'сметан|майонез|кетчуп|горчиц|соус|варень|джем|хрен|каймак|йогурт|сыр|брынз|фет|оливк|крекер|даикон|каперс' then 20
  when lower(g.name) ~ 'сахар|пудр|мёд|мед' then 10
  when lower(g.name) ~ 'кинз|лук|мят|базилик|зелень|ростк|подач|стебл.*сельдер|капуст|огурец|помидор|редис|перец сладк|лайм|лимон|фрукт|ягод' then 15
  else 10
end,
unit = case
  when lower(g.name) ~ 'масл|уксус|лимонн.*сок|сок лайм|соев.*соус|сироп' then 'ml'
  else 'g'
end
from public.global_ingredient_catalog g
where i.ingredient_id=g.id and i.quantity is null;

-- Complete the missing/short technologies in Russian. Existing rich cards are left intact.
update public.global_recipe_catalog set description='Классический американо: двойной эспрессо с горячей водой, подаваемый без молока.', steps='[{"text":{"ru":"Подготовьте кофемашину: прогрейте группу и чашку, проверьте чистоту фильтра и рабочую температуру."},"minutes":2},{"text":{"ru":"Сформируйте порцию молотого кофе 9 г, равномерно распределите в портафильтре и утрамбуйте таблетку."},"minutes":1},{"text":{"ru":"Приготовьте эспрессо объёмом около 30 мл за стандартное время экстракции, не допуская перегрева и горечи."},"minutes":1},{"text":{"ru":"Нагрейте воду до горячего состояния без активного кипения; отмерьте около 220 мл."},"minutes":2},{"text":{"ru":"Налейте горячую воду в чашку и аккуратно добавьте свежеприготовленный эспрессо."},"minutes":1},{"text":{"ru":"Подавайте сразу; напиток должен быть горячим, с чистым кофейным ароматом и без молочной пены."},"minutes":1}]'::jsonb where id='1b6c96df-8d4c-4b13-90dd-8851f6cb20b2';

update public.global_recipe_catalog set description='Тонкие классические блины на молоке: замешиваются из жидкого однородного теста и быстро выпекаются на горячей сковороде.', steps='[{"text":{"ru":"Соедините яйцо, сахар и соль, перемешайте венчиком до однородности."},"minutes":2},{"text":{"ru":"Влейте примерно половину молока и постепенно всыпьте просеянную муку, постоянно перемешивая."},"minutes":3},{"text":{"ru":"Добавьте оставшееся молоко и растительное масло. Размешайте до гладкого теста без комков."},"minutes":2},{"text":{"ru":"Дайте тесту постоять 10 минут, чтобы мука полностью гидратировалась и блины получались эластичными."},"minutes":10},{"text":{"ru":"Хорошо разогрейте сковороду, слегка смажьте её маслом и налейте тонкий слой теста."},"minutes":2},{"text":{"ru":"Выпекайте 30–60 секунд с первой стороны и около 20–30 секунд со второй до равномерного золотистого цвета."},"minutes":12},{"text":{"ru":"Готовые блины складывайте стопкой. Перед подачей подавайте горячими или охладите и используйте для начинки."},"minutes":3}]'::jsonb where id='084a183c-968f-4fa5-9848-f7220ebd8b6e';

update public.global_recipe_catalog set description='Классический бургер с говяжьей котлетой, свежими овощами, маринованным огурцом, кетчупом и майонезным соусом.', steps='[{"text":{"ru":"Сформуйте из 130 г говяжьего фарша плоскую котлету чуть шире булочки. Придайте ей одинаковую толщину."},"minutes":3},{"text":{"ru":"Посолите и поперчите котлету непосредственно перед жаркой."},"minutes":1},{"text":{"ru":"Обжарьте котлету на хорошо разогретой поверхности по 3–4 минуты с каждой стороны до полной готовности и румяной корочки."},"minutes":8},{"text":{"ru":"Разрежьте булочку и подрумяньте срезы на сухой сковороде 30–60 секунд."},"minutes":2},{"text":{"ru":"На нижнюю половину нанесите майонез и кетчуп. Добавьте листья салата, ломтики помидора и маринованный огурец."},"minutes":2},{"text":{"ru":"Положите горячую котлету, сверху добавьте оставшийся соус и накройте верхней половиной булочки."},"minutes":1},{"text":{"ru":"Подавайте сразу, пока булочка хрустящая, а котлета сочная и горячая."},"minutes":1}]'::jsonb where id='ebd35d8c-c99d-4e52-bf7a-db06334e3bc3';

update public.global_recipe_catalog set description='Капучино на основе эспрессо и текстурированного молока с плотной мелкой пеной, подаваемый горячим.', steps='[{"text":{"ru":"Приготовьте эспрессо из 9 г кофе и перелейте в прогретую чашку."},"minutes":2},{"text":{"ru":"Охладите свежую порцию молока в питчере и начните нагрев паром, одновременно создавая мелкую микропену."},"minutes":2},{"text":{"ru":"Нагрейте молоко примерно до 60–65 °C. Пена должна быть глянцевой, мелкопористой и без крупных пузырей."},"minutes":2},{"text":{"ru":"Слегка постучите питчером о рабочую поверхность и прокрутите молоко, чтобы пена стала однородной."},"minutes":1},{"text":{"ru":"Аккуратно влейте молоко в эспрессо, сохраняя соотношение насыщенной кофейной части и молочной пены."},"minutes":1},{"text":{"ru":"Подавайте сразу при температуре, комфортной для гостя."},"minutes":1}]'::jsonb where id='c3976541-e815-49ce-8beb-a22637611b9e';

update public.global_recipe_catalog set description='Паста карбонара по имеющейся технологической карте: спагетти с беконом, сливками, яйцом, пармезаном и чёрным перцем.', steps='[{"text":{"ru":"Поставьте воду для пасты, посолите её и доведите до активного кипения."},"minutes":5},{"text":{"ru":"Нарежьте бекон небольшими полосками и обжарьте на среднем огне до румяности, сохранив вытопившийся жир."},"minutes":6},{"text":{"ru":"Отварите спагетти до состояния аль денте. Перед сливом сохраните около 100 мл воды от варки."},"minutes":8},{"text":{"ru":"Смешайте яйцо, сливки, мелко натёртый пармезан и свежемолотый чёрный перец."},"minutes":3},{"text":{"ru":"Переложите горячую пасту к бекону, снимите с сильного огня и быстро введите сливочно-яичную смесь, чтобы яйцо загустело от остаточного тепла, но не свернулось."},"minutes":2},{"text":{"ru":"При необходимости добавьте немного воды от варки до кремовой консистенции и скорректируйте соль."},"minutes":1},{"text":{"ru":"Подавайте сразу, сверху добавив бекон, пармезан и немного чёрного перца."},"minutes":1}]'::jsonb where id='d5986f37-87bd-486d-98c1-faf312cf82a4';

update public.global_recipe_catalog set description='Латте: одна порция эспрессо с большим количеством горячего текстурированного молока и тонким слоем микропены.', steps='[{"text":{"ru":"Приготовьте эспрессо из 9 г кофе в прогретую чашку."},"minutes":2},{"text":{"ru":"Нагрейте 250 мл молока паром, вводя небольшое количество воздуха в начале и затем формируя однородную микропену."},"minutes":3},{"text":{"ru":"Доведите молоко примерно до 60–65 °C. Не допускайте кипения и крупнопузырьковой пены."},"minutes":2},{"text":{"ru":"Прокрутите питчер, чтобы молочная текстура стала гладкой и блестящей."},"minutes":1},{"text":{"ru":"Влейте молоко в эспрессо тонкой непрерывной струёй, оставляя на поверхности небольшой слой микропены."},"minutes":1},{"text":{"ru":"Подавайте сразу в прогретой чашке."},"minutes":1}]'::jsonb where id='f9537ccc-b75b-4e10-8d12-4d3277825c0e';

update public.global_recipe_catalog set description='Освежающий домашний лимонад с лимонным соком, мятой, сахаром и охлаждённой водой.', steps='[{"text":{"ru":"Вымойте лимон, снимите немного цедры и выжмите из мякоти сок, удалив косточки."},"minutes":3},{"text":{"ru":"Разотрите мяту с сахаром, чтобы освободить эфирные масла и аромат."},"minutes":2},{"text":{"ru":"Добавьте лимонный сок и небольшое количество воды, перемешайте до растворения сахара."},"minutes":2},{"text":{"ru":"Влейте оставшуюся воду и тщательно перемешайте. Используйте охлаждённую воду для немедленной подачи."},"minutes":1},{"text":{"ru":"Процедите напиток для более чистой текстуры или оставьте мяту и цедру для домашнего вида."},"minutes":1},{"text":{"ru":"Охладите и подавайте со льдом, украсив веточкой мяты и долькой лимона."},"minutes":2}]'::jsonb where id='89077882-9f15-41b3-b7b8-b88b2d86f74e';

update public.global_recipe_catalog set description='Паста болоньезе с мясным томатным соусом, луком и морковью, доведённым до насыщенного вкуса длительным тушением.', steps='[{"text":{"ru":"Мелко нарежьте лук и морковь. Прогрейте растительное масло и обжарьте овощи до мягкости, не допуская сильного подрумянивания."},"minutes":6},{"text":{"ru":"Добавьте свино-говяжий фарш, разомните комки и обжарьте до равномерного изменения цвета."},"minutes":8},{"text":{"ru":"Добавьте измельчённые помидоры, посолите и доведите соус до слабого кипения."},"minutes":4},{"text":{"ru":"Тушите соус на слабом огне 20–30 минут, периодически перемешивая, пока мясо не станет мягким, а соус заметно не загустеет."},"minutes":30},{"text":{"ru":"Отдельно отварите спагетти до аль денте в подсоленной воде. Сохраните немного воды от варки."},"minutes":9},{"text":{"ru":"Смешайте пасту с частью соуса, при необходимости добавьте 1–2 столовые ложки воды от варки для лучшего сцепления."},"minutes":2},{"text":{"ru":"Выложите пасту порционно, сверху добавьте мясной соус и подавайте горячей."},"minutes":2}]'::jsonb where id='b0df5c77-9f73-43c5-8e7a-191694f3e8e0';

update public.global_recipe_catalog set description='Пицца Маргарита на тонкой основе с томатной основой, моцареллой, свежим помидором и растительным маслом.', steps='[{"text":{"ru":"Смешайте пшеничную муку с солью, постепенно добавьте воду до получения мягкого эластичного теста. Вымесите до гладкости."},"minutes":8},{"text":{"ru":"Накройте тесто и оставьте на 30–60 минут, чтобы оно отдохнуло и стало пластичным."},"minutes":45},{"text":{"ru":"Растяните тесто в круглую основу толщиной около 3–5 мм и перенесите на горячий противень или камень."},"minutes":5},{"text":{"ru":"Нанесите тонкий слой томатного соуса, распределите моцареллу и ломтики помидора, затем слегка сбрызните маслом."},"minutes":3},{"text":{"ru":"Выпекайте в предварительно максимально разогретой духовке при 230–250 °C до золотистой корочки основы и полного расплавления сыра."},"minutes":10},{"text":{"ru":"Дайте пицце постоять 1–2 минуты, нарежьте и отпускайте горячей."},"minutes":2}]'::jsonb where id='10b5d57c-c0eb-4c59-9805-b2734dae88c1';

update public.global_recipe_catalog set description='Ванильный раф на основе эспрессо, сливок, ванильного сиропа и ванильного сахара, взбитый до однородной кремовой текстуры.', steps='[{"text":{"ru":"Приготовьте эспрессо из 9 г зернового кофе в питчер или небольшую термостойкую ёмкость."},"minutes":2},{"text":{"ru":"Добавьте сливки, ванильный сироп и ванильный сахар. Перемешайте до растворения сахара."},"minutes":2},{"text":{"ru":"Нагревайте смесь паром до 60–65 °C, одновременно активно перемешивая, чтобы образовалась мелкая однородная пена."},"minutes":3},{"text":{"ru":"Не доводите напиток до кипения: перегрев разрушит сливочную текстуру и усилит вкус сахара."},"minutes":1},{"text":{"ru":"Перелейте раф в прогретую чашку, удерживая пену в верхней части напитка."},"minutes":1},{"text":{"ru":"Подавайте сразу горячим."},"minutes":1}]'::jsonb where id='0c0a7134-03b8-4644-a1ce-748e995475a9';

update public.global_recipe_catalog set description='Греческий салат из свежих помидоров, огурцов, сладкого перца, лука и сыра с масляной заправкой.', steps='[{"text":{"ru":"Вымойте овощи и обсушите их, чтобы лишняя вода не разбавляла заправку."},"minutes":4},{"text":{"ru":"Нарежьте помидор крупными дольками, огурец — полукольцами или крупными кусочками, перец — полосками."},"minutes":5},{"text":{"ru":"Лук нарежьте тонкими полукольцами и при необходимости на 2–3 минуты замочите в холодной воде, чтобы смягчить резкость."},"minutes":3},{"text":{"ru":"Сложите овощи в холодную миску, добавьте сыр, посолите и поперчите."},"minutes":2},{"text":{"ru":"Заправьте маслом непосредственно перед подачей и аккуратно перемешайте, не раздавливая овощи."},"minutes":1},{"text":{"ru":"Подавайте охлаждённым или при температуре 8–12 °C."},"minutes":1}]'::jsonb where id='49b3ced3-69f6-4251-af7c-912227212000';

update public.global_recipe_catalog set description='Салат Цезарь с обжаренной курицей, хрустящим салатом Айсберг, сухариками, пармезаном и соусом Цезарь.', steps='[{"text":{"ru":"Куриное филе посолите и поперчите, обжарьте до полной готовности, затем оставьте на 2–3 минуты и нарежьте ломтиками."},"minutes":10},{"text":{"ru":"Листья Айсберга вымойте, тщательно обсушите и разорвите руками на крупные кусочки."},"minutes":4},{"text":{"ru":"Пармезан натрите или сделайте тонкими хлопьями. Подготовьте сухарики так, чтобы они были сухими и хрустящими."},"minutes":3},{"text":{"ru":"Смешайте салат с частью соуса Цезарь непосредственно перед подачей."},"minutes":1},{"text":{"ru":"Выложите салат горкой, распределите ломтики курицы, сухарики и пармезан."},"minutes":2},{"text":{"ru":"Добавьте оставшийся соус тонкими полосами и подавайте сразу, пока сухарики сохраняют хруст."},"minutes":1}]'::jsonb where id='d7d636a9-80d6-484a-8df3-c0963399e92c';

update public.global_recipe_catalog set description='Нежные сырники из творожной массы с яйцом, небольшим количеством муки и сахара, обжаренные до румяной корочки.', steps='[{"text":{"ru":"Смешайте творожную основу, яйцо и сахар до однородной массы без крупных комков."},"minutes":3},{"text":{"ru":"Добавьте муку и быстро перемешайте. Не вымешивайте массу слишком долго, чтобы сырники не стали плотными."},"minutes":2},{"text":{"ru":"Дайте массе постоять 5–10 минут, затем сформуйте сырники одинакового веса и толщины."},"minutes":10},{"text":{"ru":"Обжарьте на сливочном масле на среднем огне до золотистой корочки с обеих сторон."},"minutes":6},{"text":{"ru":"Убавьте огонь и доведите сырники под крышкой ещё 2–3 минуты, чтобы середина прогрелась."},"minutes":3},{"text":{"ru":"Подавайте горячими со сметаной или ягодным соусом."},"minutes":2}]'::jsonb where id='cf8b50f5-8479-4f1b-998b-765d2ddd3860';

update public.global_recipe_catalog set description='Классический хот-дог с горячей сосиской в мягкой булочке, кетчупом и горчицей.', steps='[{"text":{"ru":"Разогрейте сосиску на гриле, сковороде или в воде до температуры подачи, не допуская пересушивания."},"minutes":4},{"text":{"ru":"Сделайте продольный надрез в булочке, не разрезая её полностью."},"minutes":1},{"text":{"ru":"Прогрейте булочку на сухой поверхности 30–60 секунд, чтобы она стала мягкой внутри и слегка подрумянилась."},"minutes":1},{"text":{"ru":"Нанесите кетчуп и горчицу по внутренней стороне булочки."},"minutes":1},{"text":{"ru":"Уложите горячую сосиску в булочку по центру."},"minutes":1},{"text":{"ru":"При необходимости добавьте дополнительные соусы или гарнир. Подавайте сразу."},"minutes":1}]'::jsonb where id='5925f529-ed6e-45d1-80d7-56aef1981c09';

update public.global_recipe_catalog set description='Чизбургер с говяжьей котлетой, расплавленным сыром Чеддер, маринованным огурцом, помидором, луком и соусами.', steps='[{"text":{"ru":"Сформуйте котлету из 120 г говяжьего фарша, сохраняя равномерную толщину и слегка углубляя центр."},"minutes":3},{"text":{"ru":"Посолите и поперчите и обжарьте котлету на сильном огне до румяной корочки и полной готовности."},"minutes":7},{"text":{"ru":"За 30–60 секунд до готовности положите на котлету ломтик Чеддера и дайте сыру полностью расплавиться."},"minutes":1},{"text":{"ru":"Подрумяньте обе половины булочки срезом вниз."},"minutes":2},{"text":{"ru":"На нижнюю половину нанесите майонез и кетчуп, добавьте лук, помидор и маринованный огурец."},"minutes":2},{"text":{"ru":"Уложите горячую котлету с сыром и накройте верхней половиной булочки."},"minutes":1},{"text":{"ru":"Подавайте немедленно, пока сыр расплавлен, а котлета сохраняет сочность."},"minutes":1}]'::jsonb where id='d28bc12a-df6f-4a2e-a7cd-577620892d85';

update public.global_recipe_catalog set description='Классическая шаурма с обжаренным куриным филе, свежей капустой, огурцом, помидором, луком и фирменным соусом в лаваше.', steps='[{"text":{"ru":"Куриное филе нарежьте небольшими полосками, посолите и приправьте по технологической карте."},"minutes":4},{"text":{"ru":"Обжарьте курицу на хорошо разогретой поверхности до полной готовности и румяной корочки."},"minutes":8},{"text":{"ru":"Капусту тонко нашинкуйте, огурец и помидор нарежьте полосками, лук — тонкими полукольцами."},"minutes":5},{"text":{"ru":"Разложите лаваш, нанесите фирменный соус и распределите овощи равномерным слоем."},"minutes":2},{"text":{"ru":"Добавьте горячую курицу, подверните боковые края и плотно сверните шаурму в рулет."},"minutes":2},{"text":{"ru":"Подрумяньте шаурму на гриле или сухой сковороде до румяных следов и прогрева всей начинки."},"minutes":3},{"text":{"ru":"Разрежьте по диагонали и подавайте сразу."},"minutes":1}]'::jsonb where id='1d6a66b0-da5e-451f-8817-43aadd70a8b2';

update public.global_recipe_catalog set description='Шаурма Цезарь с горячей курицей, хрустящим Айсбергом, помидором, сухариками, пармезаном и соусом Цезарь.', steps='[{"text":{"ru":"Куриное филе посолите и обжарьте до полной готовности, после короткого отдыха нарежьте полосками."},"minutes":10},{"text":{"ru":"Айсберг нарежьте крупными полосками, помидор — небольшими ломтиками, пармезан подготовьте тонкой стружкой."},"minutes":4},{"text":{"ru":"Лаваш разложите и нанесите соус Цезарь по центральной части."},"minutes":1},{"text":{"ru":"Выложите Айсберг, помидор, сухарики, пармезан и горячую курицу."},"minutes":2},{"text":{"ru":"Добавьте ещё немного соуса, заверните боковые края и скрутите плотным рулетом."},"minutes":2},{"text":{"ru":"Поджарьте с двух сторон на гриле или сковороде до лёгкой корочки."},"minutes":3},{"text":{"ru":"Разрежьте и подавайте сразу, чтобы сухарики не потеряли хруст."},"minutes":1}]'::jsonb where id='b99d94b5-77ec-42c4-a97f-e1251a58beb8';

update public.global_recipe_catalog set description='Классический эспрессо: концентрированный кофейный напиток объёмом около 30 мл с плотной кремовой пенкой.', steps='[{"text":{"ru":"Прогрейте кофемашину и чашку. Используйте свежемолотый кофе."},"minutes":2},{"text":{"ru":"Отмерьте 9 г кофе, распределите его в портафильтре и равномерно утрамбуйте."},"minutes":1},{"text":{"ru":"Установите портафильтр и приготовьте эспрессо объёмом около 30 мл, контролируя равномерность экстракции."},"minutes":1},{"text":{"ru":"Оцените результат: напиток должен иметь выраженный аромат, плотную кремовую пенку и сбалансированный вкус без жжёной горечи."},"minutes":1},{"text":{"ru":"Подавайте сразу в прогретой чашке."},"minutes":1}]'::jsonb where id='9a318cf2-636a-4d34-9308-68b16ab4e215';

update public.global_recipe_catalog set steps='[{"text":{"ru":"Вымойте и обсушите свежие овощи. Подготовьте их к нарезке."},"minutes":4},{"text":{"ru":"Нарежьте помидоры крупными дольками, огурцы — полукольцами, перец — полосками."},"minutes":5},{"text":{"ru":"Лук нарежьте тонкими полукольцами и соедините с овощами."},"minutes":2},{"text":{"ru":"Добавьте сыр, соль, масло и аккуратно перемешайте."},"minutes":2},{"text":{"ru":"Оформите салат порционно и подавайте сразу после заправки, пока овощи сохраняют хруст и сок не вытягивает их структуру."},"minutes":1}]'::jsonb where id='6ea646cc-a493-4742-9530-88b08ed19fb0';

update public.global_recipe_catalog set base_servings=case when yield_unit='pcs' and yield_quantity is not null then greatest(1,yield_quantity) else 1 end where is_active=true and base_servings is null;

commit;